import {evidence,draft,gate,approver,margin,canExport} from './core.mjs';
const $=id=>document.getElementById(id);let state={revision:1,approved:null};let currentHash='';let approvedAt='';
function read(){return {...state,primary:$('primary').value,backup:$('backup').value,channel:$('channel').checked,review:$('review').checked};}
async function render(){const revision=state.revision;const data=evidence($('scenario').value,$('correction').value);$('revision').textContent=`Revisión ${revision}`;$('evidence').replaceChildren();for(const [k,title]of [['confirmed','Confirmado'],['unverified','Sin verificar'],['unknown','Desconocido']]){const card=document.createElement('article');card.className=k;const b=document.createElement('span');b.className='badge';b.textContent=title;card.append(b);data[k].forEach(line=>{const p=document.createElement('p');p.textContent=line;card.append(p)});$('evidence').append(card)}$('draft').textContent=draft($('scenario').value,$('correction').value);const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(data)));if(revision!==state.revision)return;currentHash=[...new Uint8Array(hash)].map(v=>v.toString(16).padStart(2,'0')).join('');$('hash').textContent=currentHash;sync();}
function sync(){const s=read();if(!canExport(s)){$('exportPanel').hidden=true;$('exportText').value='';}$('download').disabled=!canExport(s);$('approvalStatus').textContent=canExport(s)?`Revisión ${s.revision} aprobada por ${approver(s)}.`:gate(s)||'Pendiente: registra la aprobación de esta revisión.';}
for(const id of ['scenario','correction','primary','backup'])$(id).addEventListener('change',()=>{state.revision++;state.approved=null;approvedAt='';$('review').checked=false;$('download').disabled=true;currentHash='';render()});$('channelChoice').addEventListener('change',()=>{$('channel').checked=false;state.approved=null;sync()});for(const id of ['channel','review'])$(id).addEventListener('change',()=>{state.approved=null;sync()});
$('approve').onclick=()=>{const error=gate(read());if(error){$('approvalStatus').textContent=error;return;}state.approved=state.revision;approvedAt=new Date().toISOString();sync()};
$('download').onclick=()=>{if(!canExport(read()))return;const content=`ENSAYO · DATOS FICTICIOS · IA SIMULADA\nNo se ha enviado ningún mensaje.\nRevisión ${state.revision}\nAprobador del ensayo: ${approver(read())}\nFecha de aprobación (UTC): ${approvedAt}\nFuente: notas estructuradas del escenario ficticio, revisión ${state.revision}.\nCorrecciones: informar a Laura o Carlos por el canal alterno conocido; corregir evidencia y solicitar una nueva aprobación.\nCanal del ensayo: ${$('channelChoice').selectedOptions[0].textContent}\n\n${$('draft').textContent}\n\nSHA-256 de evidencia: ${currentHash}\nEsta huella no acredita veracidad ni admisibilidad legal.`;$('exportText').value=content;$('exportPanel').hidden=false;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='CLARA_mensaje_ensayo.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('escalate').onclick=()=>{$('escalation').textContent='Escalamiento preparado (simulado): proveedor técnico para causa y acceso a registros; administradora o suplente para comunicación. No se ha contactado a nadie.'};
$('reset').onclick=()=>location.reload();function costs(){const result=margin(['price','hours','rate','support','overhead'].map(id=>$(id).value));$('margin').textContent=result===null?'Introduce números dentro de los límites de cada campo.':`Margen estimado: ${new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(result)}`;}$('money').addEventListener('input',costs);costs();render();
